.uv-ocp {
  --c1: #6d28d9;
  --c2: #ede9fe;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-ocp {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 16em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uv-ocp .pg {
  position: absolute;
  inset: 0;
  padding: 1.2em;
  display: grid;
  align-content: start;
  gap: .55em;
}

.uv-ocp .pg i {
  height: .6em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-ocp .pg .h {
  width: 45%;
  height: 1em;
  margin-bottom: .4em;
  background: color-mix(in srgb,var(--fg) 12%,transparent);
}

.uv-ocp .pg .s {
  width: 60%;
}

.uv-ocp .scr {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: rgba(10,12,20,.35);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
  opacity: 0;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ocp.open .scr {
  opacity: 1;
  pointer-events: auto;
}

.uv-ocp .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: 1em;
  top: 1em;
  z-index: 1;
  padding: .5em .9em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 650;
  color: var(--bg);
  background: var(--fg);
}

.uv-ocp button:focus-visible,.uv-ocp a:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-ocp kbd {
  font: 600 .7em/1 ui-monospace,"SF Mono",Menlo,monospace;
  padding: .3em .45em;
  border-radius: .35em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  box-shadow: inset 0 -1px 0 color-mix(in srgb,var(--fg) 9%,transparent);
}

.uv-ocp .fire kbd {
  color: inherit;
  background: rgba(255,255,255,.18);
  box-shadow: none;
  margin-left: .3em;
}

.uv-ocp .dl {
  position: absolute;
  left: 50%;
  top: 1.6em;
  z-index: 5;
  width: 19em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.6em 3.2em -1.2em rgba(0,0,0,.5);
  transform: translateX(-50%) scale(.96);
  opacity: 0;
  pointer-events: none;
  transition: all calc(0.25s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uv-ocp.open .dl {
  transform: translateX(-50%);
  opacity: 1;
  pointer-events: auto;
}

.uv-ocp .sb {
  display: flex;
  align-items: center;
  gap: .5em;
  padding: .75em .9em;
  border-bottom: 1px solid color-mix(in srgb,var(--fg) 9%,transparent);
}

.uv-ocp .sb svg {
  width: 1.05em;
  height: 1.05em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ocp input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  font: inherit;
  color: var(--fg);
}

.uv-ocp input::placeholder {
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ocp ul {
  list-style: none;
  margin: 0;
  padding: .35em;
  max-height: 9.5em;
  overflow-y: auto;
}

.uv-ocp .gp {
  padding: .5em .6em .25em;
  font-size: .68em;
  font-weight: 700;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ocp .op {
  display: flex;
  align-items: center;
  gap: .6em;
  padding: .5em .6em;
  border-radius: .6em;
  font-size: .88em;
  cursor: pointer;
}

.uv-ocp .op svg {
  width: 1.05em;
  height: 1.05em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ocp .op kbd {
  margin-left: auto;
}

.uv-ocp .op[aria-selected="true"] {
  color: var(--c1);
  background: var(--c2);
}

.uv-ocp .op[aria-selected="true"] svg {
  color: var(--c1);
}

.uv-ocp [hidden] {
  display: none;
}

.uv-ocp .em {
  display: none;
  padding: 1em;
  text-align: center;
  font-size: .85em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ocp ul.none .em {
  display: block;
}

