.uv-osh {
  --c1: #0a84ff;
  --c2: #e5f1ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-osh {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 16em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
  height: 18em;
}

.uv-osh .pg {
  position: absolute;
  inset: 0;
  padding: 1.2em;
  display: grid;
  align-content: start;
  gap: .55em;
}

.uv-osh .pg i {
  height: .6em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-osh .pg .h {
  width: 45%;
  height: 1em;
  margin-bottom: .4em;
  background: color-mix(in srgb,var(--fg) 12%,transparent);
}

.uv-osh .pg .s {
  width: 60%;
}

.uv-osh .scr {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: rgba(10,12,20,.35);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
  opacity: 0;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-osh.open .scr {
  opacity: 1;
  pointer-events: auto;
}

.uv-osh .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: 1em;
  top: 1em;
  z-index: 1;
  padding: .5em .9em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 650;
  color: var(--bg);
  background: var(--fg);
}

.uv-osh button:focus-visible,.uv-osh a:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-osh .sh {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 5;
  padding: .5em 1em 1em;
  border-radius: 1.4em 1.4em 0 0;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.6em 3.2em -1.2em rgba(0,0,0,.5);
  transform: translateY(105%);
  transition: transform calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uv-osh.open .sh {
  transform: none;
}

.uv-osh .gr {
  display: block;
  width: 2.4em;
  height: .3em;
  margin: 0 auto .8em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 18%,transparent);
}

.uv-osh .hd {
  display: flex;
  gap: .7em;
  align-items: center;
  padding-bottom: .8em;
  border-bottom: 1px solid color-mix(in srgb,var(--fg) 9%,transparent);
}

.uv-osh .th {
  width: 2.6em;
  height: 2.6em;
  border-radius: .6em;
  background: linear-gradient(160deg,#9be15d,#00a3a1);
}

.uv-osh .hd b {
  display: block;
  font-size: .88em;
}

.uv-osh .hd small {
  font-size: .72em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-osh .pp,.uv-osh .ap {
  display: flex;
  gap: .3em;
  padding: .8em 0 .2em;
  overflow-x: auto;
  scrollbar-width: none;
}

.uv-osh .pp button,.uv-osh .ap button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .35em;
  min-width: 3.6em;
  font-size: .68em;
  font-weight: 600;
  color: var(--fg);
}

.uv-osh .av {
  display: grid;
  place-items: center;
  width: 3.6em;
  height: 3.6em;
  border-radius: 50%;
  font-size: 1.25em;
  font-weight: 800;
  color: #fff;
  background: var(--c);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-osh .pp button:hover .av {
  transform: scale(1.08);
}

.uv-osh .ap svg {
  box-sizing: border-box;
  width: 3.6em;
  height: 3.6em;
  padding: 1em;
  border-radius: 1em;
  color: var(--c1);
  background: var(--c2);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-osh .ap button:hover svg {
  transform: scale(1.08);
}

.uv-osh .cp {
  display: grid!important;
}

.uv-osh .cp span {
  grid-row: 2;
  grid-column: 1;
  transition: opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-osh .cp svg {
  grid-row: 1;
  grid-column: 1;
}

.uv-osh .cp .b {
  opacity: 0;
  color: #16a34a;
}

.uv-osh .cp.ok .a {
  opacity: 0;
}

.uv-osh .cp.ok .b {
  opacity: 1;
}

.uv-osh .cp.ok svg {
  color: #fff;
  background: #16a34a;
}

