.uv-ocd {
  --c1: #111827;
  --c2: #22c55e;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-ocd {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 16em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
  height: 19em;
}

.uv-ocd .pg {
  position: absolute;
  inset: 0;
  padding: 1.2em;
  display: grid;
  align-content: start;
  gap: .55em;
}

.uv-ocd .pg i {
  height: .6em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-ocd .pg .h {
  width: 45%;
  height: 1em;
  margin-bottom: .4em;
  background: color-mix(in srgb,var(--fg) 12%,transparent);
}

.uv-ocd .pg .s {
  width: 60%;
}

.uv-ocd .scr {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: rgba(10,12,20,.35);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
  opacity: 0;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ocd.open .scr {
  opacity: 1;
  pointer-events: auto;
}

.uv-ocd .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: 1em;
  top: 1em;
  z-index: 1;
  padding: .5em .9em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 650;
  color: var(--bg);
  background: var(--fg);
}

.uv-ocd button:focus-visible,.uv-ocd a:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-ocd .fire {
  display: flex;
  align-items: center;
  gap: .35em;
}

.uv-ocd .fire svg {
  width: 1.1em;
  height: 1.1em;
}

.uv-ocd .ct {
  font-variant-numeric: tabular-nums;
}

.uv-ocd .dr {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  z-index: 5;
  display: flex;
  flex-direction: column;
  width: 16em;
  border-radius: 1.2em 0 0 1.2em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.6em 3.2em -1.2em rgba(0,0,0,.5);
  transform: translateX(105%);
  transition: transform calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uv-ocd.open .dr {
  transform: none;
}

.uv-ocd header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: .9em 1em .6em;
}

.uv-ocd .x {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 1.9em;
  height: 1.9em;
  border-radius: 50%;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-ocd .x svg {
  width: 1em;
  height: 1em;
}

.uv-ocd .fs {
  padding: 0 1em .7em;
  font-size: .72em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ocd .fs i {
  display: block;
  height: .45em;
  margin-top: .45em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  overflow: hidden;
}

.uv-ocd .fs i b {
  display: block;
  height: 100%;
  width: var(--f,50%);
  border-radius: inherit;
  background: var(--c2);
  transition: width calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1);
