  border-radius: .6em;
  background: linear-gradient(135deg,color-mix(in srgb,var(--c) 40%,#fff),var(--c));
}

.uv-ocd .tx {
  flex: 1;
  min-width: 0;
  display: grid;
}

.uv-ocd .tx b {
  font-size: .82em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.uv-ocd .tx small {
  font-size: .72em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ocd .qt {
  display: flex;
  align-items: center;
  border-radius: 2em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-ocd .qt button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  width: 1.8em;
  height: 1.8em;
  border-radius: 50%;
  font-weight: 700;
}

.uv-ocd .qt output {
  min-width: 1.2em;
  text-align: center;
  font-size: .85em;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.uv-ocd .qt output.bump {
  animation: uv-ocd calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-ocd footer {
  padding: .8em 1em 1em;
  border-top: 1px solid color-mix(in srgb,var(--fg) 9%,transparent);
}

.uv-ocd footer p {
  display: flex;
  justify-content: space-between;
  margin: 0 0 .6em;
  font-size: .9em;
}

.uv-ocd .sb {
  font-variant-numeric: tabular-nums;
}

.uv-ocd .go {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  width: 100%;
  padding: .8em;
  border-radius: .8em;
  font-weight: 700;
  color: var(--bg);
  background: var(--c1);
}

@keyframes uv-ocd {
  50% {
    transform: scale(1.4);
  }
}

