.uv-oab {
  --c1: #4f46e5;
  --c2: #ec4899;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-oab {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 16em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uv-oab .bn {
  display: grid;
  grid-template-rows: 1fr;
  transition: grid-template-rows calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uv-oab.closed .bn {
  grid-template-rows: 0fr;
}

.uv-oab .in {
  position: relative;
  display: flex;
  align-items: center;
  gap: .6em;
  min-height: 0;
  overflow: hidden;
  padding: 0 .8em;
  color: #fff;
  background: linear-gradient(90deg,var(--c1),var(--c2));
}

.uv-oab .in::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(105deg,transparent 35%,rgba(255,255,255,.35) 50%,transparent 65%) 0 0/250% 100%;
  animation: uv-oab calc(3.5s / var(--k)) linear infinite;
  pointer-events: none;
}

.uv-oab .in>* {
  position: relative;
  margin: .7em 0;
}

.uv-oab .tg {
  padding: .2em .5em;
  border-radius: .4em;
  font-size: .68em;
  font-weight: 800;
  color: var(--c1);
  background: #fff;
}

.uv-oab .tx {
  flex: 1;
  min-width: 0;
  font-size: .8em;
  font-weight: 600;
  line-height: 1.3;
}

.uv-oab a {
  font-size: .78em;
  font-weight: 800;
  color: #fff;
  text-underline-offset: .2em;
  white-space: nowrap;
}

.uv-oab .x {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 1.7em;
  height: 1.7em;
  border-radius: 50%;
  color: #fff;
}

.uv-oab .x:hover {
  background: rgba(255,255,255,.2);
}

.uv-oab .x svg {
  width: 1em;
  height: 1em;
}

.uv-oab a:focus-visible,.uv-oab .x:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

.uv-oab .ap {
  position: relative;
  height: 100%;
}

.uv-oab .nb {
  display: flex;
  gap: .5em;
  align-items: center;
  padding: .9em 1.2em;
  border-bottom: 1px solid color-mix(in srgb,var(--fg) 9%,transparent);
}

.uv-oab .nb i {
  width: 3em;
  height: .6em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-oab .nb i:first-child {
  width: 1.6em;
  height: 1.6em;
  border-radius: .5em;
  background: color-mix(in srgb,var(--c1) 30%,transparent);
}

.uv-oab .pg {
  position: relative;
  padding: 1.2em;
  display: grid;
  gap: .55em;
}

.uv-oab .pg i {
  height: .6em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-oab .pg .h {
  width: 45%;
  height: 1em;
  background: color-mix(in srgb,var(--fg) 12%,transparent);
}

.uv-oab .pg .s {
  width: 60%;
}

.uv-oab .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: 1em;
  bottom: 1em;
  padding: .5em .9em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 650;
  color: var(--bg);
  background: var(--fg);
  opacity: 0;
  transform: translateY(.5em);
  pointer-events: none;
  transition: all calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-oab.closed .fire {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

.uv-oab .fire:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@keyframes uv-oab {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: -150% 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-oab,.uv-oab *,.uv-oab *::before,.uv-oab *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

