.uv-ost {
  --c1: #f59e0b;
  --c2: #2563eb;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --secs: 30;
  /* duración */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-ost {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 16em;
