  height: 18em;
}

.uv-ost .pg {
  position: absolute;
  inset: 0;
  padding: 1.2em;
  display: grid;
  align-content: start;
  gap: .55em;
}

.uv-ost .pg i {
  height: .6em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-ost .pg .h {
  width: 45%;
  height: 1em;
  margin-bottom: .4em;
  background: color-mix(in srgb,var(--fg) 12%,transparent);
}

.uv-ost .pg .s {
  width: 60%;
}

.uv-ost .scr {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: rgba(10,12,20,.35);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
  opacity: 0;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ost.open .scr {
  opacity: 1;
  pointer-events: auto;
}

.uv-ost .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: 1em;
  top: 1em;
  z-index: 1;
  padding: .5em .9em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 650;
  color: var(--bg);
  background: var(--fg);
}

.uv-ost button:focus-visible,.uv-ost a:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-ost .dl {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 5;
  width: 16em;
  padding: 1.2em;
  border-radius: 1.3em;
  text-align: center;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.6em 3.2em -1.2em rgba(0,0,0,.5);
  transform: translate(-50%,-46%) scale(.95);
  opacity: 0;
  pointer-events: none;
  transition: all calc(0.35s / var(--k)) cubic-bezier(.22,1,.36,1);
  --p: 1;
}

.uv-ost.open .dl {
  transform: translate(-50%,-50%);
  opacity: 1;
  pointer-events: auto;
}

.uv-ost .rg {
  position: relative;
  width: 4.4em;
  height: 4.4em;
  margin: 0 auto .7em;
}

.uv-ost .rg svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.uv-ost .rg circle {
  fill: none;
  stroke-width: 3.5;
}

.uv-ost .rg .bg {
  stroke: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-ost .rg .fg {
  stroke: var(--c1);
