  const fire=el.querySelector(".fire"),scr=el.querySelector(".scr"),pnl=el.querySelector(".cn");let tms=[];const later=(f,ms)=>tms.push(setTimeout(f,ms));
const foc=(t,ms)=>later(()=>{const n=typeof t==="string"?el.querySelector(t):t;n&&n.focus({preventScroll:true})},ms||0);
const isOpen=()=>el.classList.contains("open");
const open=u=>{if(isOpen())return;el.classList.add("open");pnl.inert=false;fire&&fire.setAttribute("aria-expanded","true");u?foc(inp,360):demo()};
const close=()=>{if(!isOpen())return;el.classList.remove("open");pnl.inert=true;fire&&fire.setAttribute("aria-expanded","false");inp.blur();fire&&fire.focus({preventScroll:true})};
fire&&fire.addEventListener("click",()=>isOpen()?close():open(true));scr&&scr.addEventListener("click",()=>close());
el.addEventListener("keydown",e=>{if(!isOpen())return;if(e.key==="Escape"){e.preventDefault();e.stopPropagation();close()}else if(e.key==="Tab"){const f=[...pnl.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea,a[href],[tabindex="0"]')].filter(x=>x.getClientRects().length);if(!f.length){e.preventDefault();return}const a=f[0],z=f[f.length-1],ac=document.activeElement;if(e.shiftKey&&(ac===a||!pnl.contains(ac))){e.preventDefault();z.focus()}else if(!e.shiftKey&&(ac===z||!pnl.contains(ac))){e.preventDefault();a.focus()}}});
pnl.inert=true;later(()=>open(false),500);const inp=el.querySelector(".cn input"),lg=el.querySelector(".lg"),lib=el.querySelector(".lib");const hist=[];let hi=0,shown=false;
const say=(t,c)=>{const p=document.createElement("p");p.textContent=t;if(c)p.className=c;lg.appendChild(p);while(lg.children.length>40)lg.firstElementChild.remove();lg.scrollTop=lg.scrollHeight};
const run=v=>{const c=v.trim().toLowerCase();if(!c)return;say("] "+v.trim(),"me");hist.push(v.trim());hi=hist.length;if(c==="clear"){lg.textContent="";return}if(c==="quit"||c==="exit"){close();return}if(c==="god")el.classList.toggle("god");const m=[...lib.children].find(p=>p.dataset.c===c)||lib.querySelector("[data-c='?']");say(m.textContent+(m.dataset.c==="?"?": "+c:""))};
const demo=()=>{if(shown)return;shown=true;let i=0;const s="help";const ty=()=>{if(i<s.length){inp.value+=s[i++];later(ty,110)}else later(()=>{run(inp.value);inp.value=""},260)};later(ty,700)};
inp.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();run(inp.value);inp.value=""}else if(e.key==="ArrowUp"&&hist.length){e.preventDefault();hi=Math.max(0,hi-1);inp.value=hist[hi]}else if(e.key==="ArrowDown"&&hist.length){e.preventDefault();hi=Math.min(hist.length,hi+1);inp.value=hist[hi]||""}});
el.addEventListener("keydown",e=>{if(e.code==="Backquote"||e.key==="º"||e.key==="ª"){e.preventDefault();isOpen()?close():open(true)}});return()=>tms.forEach(clearTimeout)
});

