.uvq13-pip {
  --c1: #fb7a3c;
  --c2: #0f766e;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq13-pip {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 17em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-pip .pg {
  position: absolute;
  inset: 0;
  padding: 1.2em;
  display: grid;
  align-content: start;
  gap: .55em;
}

.uvq13-pip .pg i {
  height: .6em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq13-pip .pg .h {
  width: 45%;
  height: 1em;
  margin-bottom: .4em;
  background: color-mix(in srgb,var(--fg) 12%,transparent);
}

.uvq13-pip .pg .s {
  width: 60%;
}

.uvq13-pip .scr {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: rgba(10,12,20,.38);
  opacity: 0;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-pip.open .scr {
  opacity: 1;
  pointer-events: auto;
}

.uvq13-pip .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: 1em;
  top: 1em;
  z-index: 1;
  padding: .55em .95em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 650;
  color: var(--bg);
  background: var(--fg);
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-pip .fire:active {
  transform: scale(.96);
}

.uvq13-pip button:focus-visible,.uvq13-pip a:focus-visible,.uvq13-pip input:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq13-pip .hn {
  position: absolute;
  left: 1.2em;
  bottom: 1.2em;
  margin: 0;
  font-size: .74em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-pip .fire {
  opacity: 0;
  pointer-events: none;
  transform: scale(.9);
}

.uvq13-pip.gone .fire {
  opacity: 1;
  pointer-events: auto;
  transform: none;
}

.uvq13-pip .pw {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 6;
  width: 9.6em;
  aspect-ratio: 16/9;
  border-radius: .8em;
  overflow: hidden;
  background: #111;
  box-shadow: 0 0 0 1px rgba(255,255,255,.08),0 1em 2em -.8em rgba(0,0,0,.65);
  transform-origin: 0 0;
  cursor: grab;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  transition: transform calc(0.55s / var(--k)) cubic-bezier(.34,1.56,.64,1),opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),border-radius calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-pip .pw.dr {
  transition: none;
  cursor: grabbing;
}

.uvq13-pip .pw.big {
  cursor: default;
}

.uvq13-pip.gone .pw {
  opacity: 0;
  pointer-events: none;
}

.uvq13-pip .pw:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq13-pip .vd {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: linear-gradient(180deg,#26335f 0%,#7a4a7e 42%,var(--c1) 72%,#ffd08a 80%);
}

.uvq13-pip .vd i {
  position: absolute;
  display: block;
}

.uvq13-pip .sun {
  left: 56%;
  top: 48%;
  width: 2.2em;
  height: 2.2em;
  border-radius: 50%;
  background: radial-gradient(circle,#fff7d6,#ffd27a 55%,transparent 70%);
}

.uvq13-pip .cl {
  left: -3em;
  top: 16%;
  width: 2.6em;
  height: .65em;
  border-radius: 1em;
