  box-shadow: 4em .7em 0 -.1em rgba(255,255,255,.4),8.5em -.2em 0 -.15em rgba(255,255,255,.35);
  animation: uvq13-pip-c calc(9s / var(--k)) linear infinite;
}

.uvq13-pip .h1 {
  left: -10%;
  right: 20%;
  bottom: -38%;
  height: 75%;
  border-radius: 50% 50% 0 0;
  background: color-mix(in srgb,var(--c2) 80%,#000);
}

.uvq13-pip .h2 {
  left: 35%;
  right: -30%;
  bottom: -48%;
  height: 80%;
  border-radius: 50% 50% 0 0;
  background: color-mix(in srgb,var(--c2) 45%,#000);
}

.uvq13-pip .pa .vd *,.uvq13-pip .pa .pb b {
  animation-play-state: paused;
}

.uvq13-pip .ct {
  position: absolute;
  inset: 0;
  display: flex;
  justify-content: flex-end;
  gap: .3em;
  padding: .4em;
  background: linear-gradient(180deg,rgba(0,0,0,.45),transparent 45%,transparent 70%,rgba(0,0,0,.4));
  opacity: 0;
  transition: opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-pip .pw:hover .ct,.uvq13-pip .pw:focus-within .ct,.uvq13-pip .big .ct,.uvq13-pip .pa .ct {
  opacity: 1;
}

@media (hover:none) {
  .uvq13-pip .ct {
    opacity: 1;
  }
}

.uvq13-pip .ct button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 1.65em;
  height: 1.65em;
  border-radius: 50%;
  color: #fff;
  background: rgba(0,0,0,.38);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq13-pip .ct button:hover {
  transform: scale(1.1);
}

.uvq13-pip .ct button svg {
  width: .9em;
  height: .9em;
}

.uvq13-pip .ct .pl {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 2.2em;
  height: 2.2em;
  margin: -1.1em;
}

.uvq13-pip .ct .pl svg {
  width: 1.1em;
  height: 1.1em;
}

.uvq13-pip .pl .i1,.uvq13-pip .pa .pl .i2 {
  display: none;
}

.uvq13-pip .pa .pl .i1 {
  display: block;
}

.uvq13-pip .ct button:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

.uvq13-pip .pb {
  position: absolute;
  left: .55em;
  right: .55em;
  bottom: .45em;
  height: .18em;
  border-radius: 1em;
  background: rgba(255,255,255,.3);
  overflow: hidden;
}

.uvq13-pip .pb b {
  display: block;
  height: 100%;
  background: #fff;
  transform-origin: 0 0;
  animation: uvq13-pip-p calc(40s / var(--k)) linear infinite;
}

@keyframes uvq13-pip-c {
  to {
    transform: translateX(15em);
  }
}

@keyframes uvq13-pip-p {
  from {
    transform: scaleX(0);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq13-pip,.uvq13-pip *,.uvq13-pip *::before,.uvq13-pip *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

