  const pw=el.querySelector(".pw"),fire=el.querySelector(".fire"),scr=el.querySelector(".scr"),pl=el.querySelector(".pl"),ex=el.querySelector(".ex");let cx=1,cy=1,big=false,x=0,y=0,d=null;const M=12;
const sc=()=>el.getBoundingClientRect().width/el.offsetWidth||1;
const put=(nx,ny,s)=>{x=nx;y=ny;pw.style.transform="translate("+nx+"px,"+ny+"px) scale("+(s||1)+")"};
const snap=()=>{const W=el.clientWidth,H=el.clientHeight,w=pw.offsetWidth,h=pw.offsetHeight;if(big){const s=Math.min(W*.86/w,H*.8/h);put((W-w*s)/2,(H-h*s)/2,s)}else put(cx?W-w-M:M,cy?H-h-M:M)};
