const up=()=>{if(!d)return;pw.classList.remove("dr");const W=el.clientWidth,H=el.clientHeight,w=pw.offsetWidth,h=pw.offsetHeight;cx=x+d.vx*200+w/2>W/2?1:0;cy=y+d.vy*200+h/2>H/2?1:0;d=null;snap()};
pw.addEventListener("pointerup",up);pw.addEventListener("pointercancel",up);
pw.addEventListener("dblclick",e=>{if(!e.target.closest("button"))setBig(!big)});
const hide=()=>{setBig(false);el.classList.add("gone");fire.focus({preventScroll:true})};
fire.addEventListener("click",()=>{el.classList.remove("gone");pw.focus({preventScroll:true})});
el.querySelector(".x").addEventListener("click",hide);ex.addEventListener("click",()=>setBig(!big));scr.addEventListener("click",()=>setBig(false));
pl.addEventListener("click",()=>{const p=pl.getAttribute("aria-pressed")==="true";pl.setAttribute("aria-pressed",String(!p));pw.classList.toggle("pa",p)});
pw.addEventListener("keydown",e=>{if(e.target!==pw)return;const m={ArrowLeft:[0,cy],ArrowRight:[1,cy],ArrowUp:[cx,0],ArrowDown:[cx,1]}[e.key];if(m&&!big){e.preventDefault();cx=m[0];cy=m[1];snap()}else if(e.key==="Enter"||e.key===" "){e.preventDefault();setBig(!big)}});
el.addEventListener("keydown",e=>{if(e.key!=="Escape")return;if(big){e.preventDefault();setBig(false);pw.focus({preventScroll:true})}else if(pw.contains(document.activeElement)){e.preventDefault();hide()}});
const ro=new ResizeObserver(()=>{if(d)return;pw.classList.add("dr");snap();requestAnimationFrame(()=>pw.classList.remove("dr"))});ro.observe(el);
pw.classList.add("dr");snap();requestAnimationFrame(()=>requestAnimationFrame(()=>pw.classList.remove("dr")));return()=>ro.disconnect()
});

