.uvq13-bp {
  --c1: #2563eb;
  --c2: #f97316;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq13-bp {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 17em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-bp .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  left: 1em;
  top: 1em;
  z-index: 6;
  display: flex;
  align-items: center;
  gap: .4em;
  padding: .5em .9em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 700;
  color: var(--bg);
  background: var(--fg);
  transition: background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-bp .fire:active {
  transform: scale(.96);
}

.uvq13-bp .fire svg {
  width: 1.15em;
  height: 1.15em;
}

.uvq13-bp .fire[aria-pressed="true"] {
  color: #fff;
  background: var(--c1);
}

.uvq13-bp button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq13-bp .cd {
  position: absolute;
  left: 4em;
  right: 4em;
  top: 3.6em;
  padding: 1em 1.2em 1.1em;
  border-radius: 1em;
  text-align: center;
  background: var(--bg);
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 .8em 1.6em -1em rgba(0,0,0,.3);
}

.uvq13-bp .av {
  display: grid;
  place-items: center;
  width: 2.6em;
  height: 2.6em;
  margin: 0 auto .5em;
  border-radius: 50%;
  font-size: .95em;
  font-weight: 800;
  color: #fff;
  background: linear-gradient(135deg,#f472b6,#f59e0b);
}

.uvq13-bp h4 {
  margin: 0 0 .15em;
  font-size: 1em;
}

.uvq13-bp .cd p {
  margin: 0 0 .8em;
  font-size: .75em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-bp .fw {
  font: inherit;
  color: inherit;
  border: 0;
