css:
.uvq13-tel {
  --c1: #9f1239;
  --c2: #f2c14e;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq13-tel {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 18em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-tel .pg {
  position: absolute;
  inset: 0;
  padding: 1.2em;
  display: grid;
  align-content: start;
  gap: .55em;
}

.uvq13-tel .pg i {
  height: .6em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq13-tel .pg .h {
  width: 45%;
  height: 1em;
  margin-bottom: .4em;
  background: color-mix(in srgb,var(--fg) 12%,transparent);
}

.uvq13-tel .pg .s {
  width: 60%;
}

.uvq13-tel .scr {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: rgba(10,12,20,.38);
  opacity: 0;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-tel.open .scr {
  opacity: 1;
  pointer-events: auto;
}

.uvq13-tel .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: 1em;
  top: 1em;
  z-index: 1;
  padding: .55em .95em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 650;
  color: var(--bg);
  background: var(--fg);
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-tel .fire:active {
  transform: scale(.96);
}

.uvq13-tel button:focus-visible,.uvq13-tel a:focus-visible,.uvq13-tel input:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq13-tel .scr {
  background: radial-gradient(55% 60% at 50% 38%,rgba(255,236,190,.28),transparent 70%),#140a0d;
}

.uvq13-tel .cu {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 6;
  width: 51%;
  pointer-events: none;
  background: linear-gradient(180deg,rgba(0,0,0,.3),transparent 25%,transparent 78%,rgba(0,0,0,.4)),repeating-linear-gradient(90deg,rgba(0,0,0,.45) 0,rgba(0,0,0,.08) .55em,rgba(255,255,255,.14) .95em,rgba(0,0,0,.08) 1.35em,rgba(0,0,0,.45) 1.9em),var(--c1);
  transform: scaleX(0);
  transition: transform calc(0.75s / var(--k)) cubic-bezier(.65,0,.35,1),border-radius calc(0.75s / var(--k)) cubic-bezier(.65,0,.35,1);
}

.uvq13-tel .cu::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: .55em;
  background: repeating-linear-gradient(90deg,var(--c2) 0 .12em,transparent .12em .3em);
  box-shadow: 0 -.12em 0 var(--c2);
}

.uvq13-tel .cu.l {
  left: 0;
  transform-origin: 0 50%;
}

.uvq13-tel .cu.r {
  right: 0;
  transform-origin: 100% 50%;
}

.uvq13-tel.open .cu {
  transform: scaleX(1);
}

.uvq13-tel.rv .cu {
  transform: scaleX(.3);
}

.uvq13-tel.rv .cu.l {
  border-bottom-right-radius: 100% 30%;
}

.uvq13-tel.rv .cu.r {
  border-bottom-left-radius: 100% 30%;
}

.uvq13-tel .vl {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  z-index: 7;
  height: 1.9em;
  background: radial-gradient(1.15em 1em at 50% 0,color-mix(in srgb,var(--c1) 82%,#000) 97%,transparent 100%) 0 .9em/2.3em 1em repeat-x,linear-gradient(color-mix(in srgb,var(--c1) 82%,#000),color-mix(in srgb,var(--c1) 82%,#000)) 0 0/100% .95em no-repeat;
  transform: translateY(-110%);
  transition: transform calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq13-tel .vl::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: .75em;
  height: .14em;
  background: var(--c2);
}

.uvq13-tel.open .vl {
  transform: none;
}

.uvq13-tel .dl {
  position: absolute;
  left: 50%;
  top: 52%;
  z-index: 8;
  box-sizing: border-box;
  width: 12em;
  padding: 1em 1.1em;
  border-radius: .4em;
  text-align: center;
  color: #2a1a10;
  background: #fbf3e2;
  box-shadow: 0 0 0 .25em #fbf3e2,0 0 0 .38em var(--c2),0 1.5em 3em -1em rgba(0,0,0,.85);
  transform: translate(-50%,-44%) scale(.92);
  opacity: 0;
  pointer-events: none;
  transition: transform calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-tel.rv .dl {
  transform: translate(-50%,-50%);
  opacity: 1;
  pointer-events: auto;
  transition-delay: calc(.35s / var(--k));
}

.uvq13-tel .dl p {
  margin: 0;
}

.uvq13-tel .kk {
  font: 700 .6em/1 ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  letter-spacing: .32em;
  text-transform: uppercase;
  color: var(--c1);
}

.uvq13-tel .ti {
  margin: .4em 0 .3em!important;
  font: italic 700 1.35em/1.05 Georgia,"Times New Roman",serif;
  letter-spacing: -.01em;
}

.uvq13-tel .dt {
  font-size: .68em;
  opacity: .75;
}

.uvq13-tel .sp {
  margin-top: .5em!important;
  font-size: .64em;
  font-weight: 700;
  color: var(--c1);
}

.uvq13-tel .ac {
  display: grid;
  gap: .3em;
  margin-top: .8em;
}

.uvq13-tel .ac button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .65em;
  border-radius: .4em;
  font-size: .78em;
  font-weight: 700;
}

.uvq13-tel .ac .go {
  color: #fff;
  background: var(--c1);
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-tel .ac .go:hover {
  transform: translateY(-1px);
}

.uvq13-tel .ac .x {
  color: #6b4f3a;
  text-decoration: underline;
  text-underline-offset: .2em;
}

.uvq13-tel .dl button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 2px;
}

@media (prefers-reduced-motion:reduce) {
  .uvq13-tel,.uvq13-tel *,.uvq13-tel *::before,.uvq13-tel *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

