.uvq13-sty {
  --c1: #ec4899;
  --c2: #f59e0b;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq13-sty {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 19em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-sty .tray {
  display: flex;
  gap: .8em;
  padding: 1em 1.1em .7em;
  border-bottom: 1px solid color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-sty .av {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  justify-items: center;
  gap: .3em;
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq13-sty .av:active {
  transform: scale(.94);
}

.uvq13-sty .rg {
  display: grid;
  place-items: center;
  width: 3.3em;
  height: 3.3em;
  box-sizing: border-box;
  padding: .17em;
  border-radius: 50%;
  background: conic-gradient(from 210deg,var(--c1),var(--c2),var(--c1));
}

.uvq13-sty .av.seen .rg {
  background: color-mix(in srgb,var(--fg) 18%,transparent);
}

.uvq13-sty .rg b {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  font-weight: 800;
  color: #fff;
  background: var(--a);
  box-shadow: 0 0 0 .16em var(--bg);
}

.uvq13-sty .av small {
  font-size: .68em;
  font-weight: 600;
}

.uvq13-sty .av:focus-visible {
  outline: 0;
}

.uvq13-sty .av:focus-visible .rg {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq13-sty .fd {
  display: grid;
  gap: .55em;
  padding: 1em 1.1em;
}

.uvq13-sty .fd i {
  height: .6em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq13-sty .fd .ph {
  height: 6em;
  border-radius: .9em;
}

.uvq13-sty .fd .s {
  width: 60%;
}

.uvq13-sty .vw {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: grid;
  place-items: center;
  background: rgba(8,8,12,.9);
  opacity: 0;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-sty.open .vw {
  opacity: 1;
  pointer-events: auto;
}

.uvq13-sty .cd {
  position: relative;
  width: 9.8em;
  height: 17.2em;
  border-radius: 1em;
  overflow: hidden;
  background: #111;
  transform: scale(.16);
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1);
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

.uvq13-sty.open .cd {
  transform: none;
}

.uvq13-sty .cd.sw {
  animation: uvq13-sty-s calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq13-sty .sc {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: linear-gradient(165deg,var(--g1),var(--g2));
  opacity: 0;
  visibility: hidden;
  transition: opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),visibility 0s linear calc(0.25s / var(--k));
}

.uvq13-sty .sc.on {
  opacity: 1;
  visibility: visible;
  transition-delay: 0s;
}

.uvq13-sty .sc::before,.uvq13-sty .sc::after {
  content: "";
  position: absolute;
}

.uvq13-sty .sc.on::before {
  animation: uvq13-sty-k calc(6s / var(--k)) ease-out both;
}

.uvq13-sty [data-s="sun"]::before {
  left: 40%;
  top: 20%;
  width: 5em;
  height: 5em;
  border-radius: 50%;
  background: radial-gradient(circle,#fff7d6,#fde68a 45%,transparent 70%);
}

.uvq13-sty [data-s="sun"]::after {
  left: 0;
  right: 0;
  bottom: 0;
  height: 42%;
  background: repeating-linear-gradient(180deg,rgba(255,255,255,.18) 0 .15em,transparent .15em .7em),linear-gradient(180deg,color-mix(in srgb,var(--g2) 70%,#000),#0b1023);
}

.uvq13-sty [data-s="cup"]::before {
  left: 50%;
  top: 40%;
  width: 6em;
  height: 6em;
  margin: -3em 0 0 -3em;
  border-radius: 50%;
  background: radial-gradient(circle,#c08457 0 30%,#7c3f1d 31% 52%,#f5f0e6 53% 62%,#e7dccb 63% 70%,transparent 71%);
  box-shadow: 0 .6em 1.2em rgba(0,0,0,.35);
}

.uvq13-sty [data-s="cup"]::after {
  left: calc(50% + 2.3em);
  top: calc(40% - .55em);
  width: 1.3em;
  height: 1.1em;
  box-sizing: border-box;
  border: .35em solid #f5f0e6;
  border-left: 0;
  border-radius: 0 1em 1em 0;
}

.uvq13-sty [data-s="hill"]::before {
  left: -30%;
  right: -30%;
  bottom: -25%;
  height: 60%;
  border-radius: 50% 50% 0 0;
  background: color-mix(in srgb,var(--g2) 75%,#000);
}

.uvq13-sty [data-s="hill"]::after {
  right: 18%;
  top: 18%;
  width: 2.2em;
  height: 2.2em;
  border-radius: 50%;
  background: #fef9c3;
  box-shadow: 0 0 1.5em #fef08a;
}

.uvq13-sty [data-s="dots"]::before {
  inset: 0;
  background: radial-gradient(circle,rgba(255,255,255,.35) 0 .25em,transparent .27em) 0 0/1.1em 1.1em;
}

.uvq13-sty [data-s="dots"]::after {
  left: 18%;
  top: 24%;
  width: 6em;
  height: 6em;
  border-radius: 50%;
  background: conic-gradient(from 30deg,#fde047,#fb7185,#38bdf8,#fde047);
  opacity: .85;
}

.uvq13-sty [data-s="wave"]::before {
  left: 0;
  right: 0;
  bottom: 0;
  height: 52%;
  background: radial-gradient(1.2em .9em at 50% 0,transparent 96%,rgba(255,255,255,.3) 100%) 0 0/2.4em 1.1em repeat,linear-gradient(180deg,color-mix(in srgb,var(--g1) 75%,#fff),var(--g1));
}

.uvq13-sty [data-s="wave"]::after {
  left: 30%;
  top: 16%;
  width: 3em;
  height: 3em;
  border-radius: 50%;
  background: #fefce8;
  opacity: .9;
}

.uvq13-sty [data-s="rain"]::before {
  left: 0;
  right: 0;
  top: -20%;
  bottom: 0;
  background: repeating-linear-gradient(105deg,transparent 0 .9em,rgba(255,255,255,.28) .9em 1em);
}

.uvq13-sty .sc.on[data-s="rain"]::before {
  animation: uvq13-sty-r calc(0.8s / var(--k)) linear infinite;
}

.uvq13-sty [data-s="rain"]::after {
  left: 14%;
  right: 14%;
  top: 12%;
  bottom: 30%;
  border: .35em solid rgba(255,255,255,.75);
  border-radius: .3em;
  background: linear-gradient(90deg,transparent calc(50% - .17em),rgba(255,255,255,.75) 0 calc(50% + .17em),transparent 0);
}

.uvq13-sty .sc p {
  position: absolute;
  left: .8em;
  right: .8em;
  bottom: 1.2em;
  z-index: 1;
  margin: 0;
  font-size: 1.1em;
  font-weight: 850;
  line-height: 1.05;
  letter-spacing: -.02em;
  color: #fff;
  text-shadow: 0 .1em .6em rgba(0,0,0,.4);
}

.uvq13-sty .bars {
  position: absolute;
  left: .55em;
  right: .55em;
  top: .55em;
  z-index: 3;
  display: flex;
  gap: .25em;
  transition: opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-sty .bars i {
  flex: 1;
  height: .17em;
  border-radius: 1em;
  background: rgba(255,255,255,.35);
  overflow: hidden;
}

.uvq13-sty .bars b {
  display: block;
  height: 100%;
  background: #fff;
  transform-origin: 0 50%;
  transform: scaleX(0);
}

.uvq13-sty .bars .done b {
  transform: none;
}

.uvq13-sty .bars .run b {
  animation: uvq13-sty-p calc(4.5s / var(--k)) linear forwards;
}

.uvq13-sty.pa .bars .run b,.uvq13-sty.hold .bars .run b {
  animation-play-state: paused;
}

.uvq13-sty .hd {
  position: absolute;
  left: .55em;
  right: .3em;
  top: 1em;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: .4em;
  font-size: .74em;
  color: #fff;
  transition: opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-sty.hold .hd,.uvq13-sty.hold .bars {
  opacity: 0;
}

.uvq13-sty .ua {
  display: grid;
  place-items: center;
  width: 1.9em;
  height: 1.9em;
  border-radius: 50%;
  font-weight: 800;
  font-size: .85em;
  background: var(--a,#888);
  box-shadow: 0 0 0 .12em #fff;
}

.uvq13-sty .hd small {
  margin-right: auto;
  opacity: .7;
}

.uvq13-sty .hd button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 2em;
  height: 2em;
  border-radius: 50%;
  color: #fff;
}

.uvq13-sty .hd svg {
  width: 1.15em;
  height: 1.15em;
}

.uvq13-sty .pz .i1,.uvq13-sty.pa .pz .i2 {
  display: none;
}

.uvq13-sty.pa .pz .i1 {
  display: block;
}

.uvq13-sty .nv {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  top: 2.6em;
  bottom: 0;
  z-index: 2;
}

.uvq13-sty .pv {
  left: 0;
  width: 35%;
}

.uvq13-sty .nx {
  right: 0;
  width: 65%;
}

.uvq13-sty .nv:focus-visible {
  outline: 2px solid #fff;
  outline-offset: -4px;
  border-radius: .8em;
}

.uvq13-sty .hd button:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 1px;
}

@keyframes uvq13-sty-p {
  to {
    transform: none;
  }
}

@keyframes uvq13-sty-k {
  from {
    transform: scale(1.15);
  }
}

@keyframes uvq13-sty-r {
  to {
    transform: translateY(16%);
  }
}

@keyframes uvq13-sty-s {
  from {
    transform: perspective(40em) rotateY(-28deg) translateX(20%);
    opacity: .5;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq13-sty,.uvq13-sty *,.uvq13-sty *::before,.uvq13-sty *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

