.uvq13-prm {
  --c1: #2563eb;
  --c2: #ef4444;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq13-prm {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 18em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-prm .tb {
  display: flex;
  align-items: center;
  gap: .7em;
  padding: .55em .7em;
  background: color-mix(in srgb,var(--fg) 6%,var(--bg));
  border-bottom: 1px solid color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-prm .dots {
  display: flex;
  gap: .3em;
}

.uvq13-prm .dots i {
  width: .55em;
  height: .55em;
  border-radius: 50%;
  background: color-mix(in srgb,var(--fg) 20%,transparent);
}

.uvq13-prm .ad {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: .3em;
  height: 2.3em;
  padding: 0 .3em;
  border-radius: 2em;
  background: var(--bg);
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
  font-size: .74em;
}

.uvq13-prm .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  flex: none;
  width: 1.9em;
  height: 1.9em;
  border-radius: 50%;
  transition: background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-prm .fire:hover {
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq13-prm.open .fire {
  color: var(--c1);
  background: color-mix(in srgb,var(--c1) 14%,transparent);
}

.uvq13-prm .fire svg,.uvq13-prm .cam svg {
  width: 1.15em;
  height: 1.15em;
}

.uvq13-prm .url {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-prm .cam {
  position: relative;
  display: none;
  place-items: center;
  width: 1.9em;
  height: 1.9em;
}

.uvq13-prm .cam i {
  position: absolute;
  right: .25em;
  top: .3em;
  width: .45em;
  height: .45em;
  border-radius: 50%;
  background: var(--c2);
  animation: uvq13-prm-d calc(1.2s / var(--k)) ease-in-out infinite;
}

.uvq13-prm[data-p="on"] .cam {
  display: grid;
}

.uvq13-prm .lob {
  display: grid;
  grid-template-columns: 1.25fr 1fr;
  gap: .6em .9em;
  align-items: center;
  padding: 1.1em;
}

.uvq13-prm .vid {
  position: relative;
  grid-row: span 2;
  display: grid;
  place-items: center;
  aspect-ratio: 4/3;
  border-radius: .8em;
  overflow: hidden;
  color: #cbd5e1;
  background: #1f2430;
}

.uvq13-prm .st {
  display: none;
  flex-direction: column;
  align-items: center;
  gap: .35em;
  padding: .5em;
  text-align: center;
  font-size: .68em;
}

.uvq13-prm .st>svg {
  width: 1.8em;
  height: 1.8em;
}

.uvq13-prm[data-p="ask"] .s0,.uvq13-prm[data-p="no"] .s2 {
  display: flex;
}

.uvq13-prm .chg {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  margin-top: .2em;
  padding: .4em .8em;
  border-radius: 2em;
  font-weight: 700;
  color: #fff;
  background: rgba(255,255,255,.16);
}

.uvq13-prm .me {
  position: absolute;
  inset: 0;
  display: none;
  background: radial-gradient(120% 90% at 30% 20%,#64748b,#1e293b);
}

.uvq13-prm[data-p="on"] .me {
  display: block;
  animation: uvq13-prm-i calc(0.5s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-prm .me i {
  position: absolute;
  display: block;
}

.uvq13-prm .me .hd {
  left: 50%;
  top: 22%;
  width: 2.4em;
  height: 2.4em;
  margin-left: -1.2em;
  border-radius: 50%;
  background: #e0b896;
  animation: uvq13-prm-b calc(3s / var(--k)) ease-in-out infinite;
}

.uvq13-prm .me .bd {
  left: 50%;
  bottom: -1.4em;
  width: 5.6em;
  height: 3.8em;
  margin-left: -2.8em;
  border-radius: 50% 50% 0 0;
  background: var(--c1);
}

.uvq13-prm .me .lv {
  right: .5em;
  bottom: .5em;
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: .9em;
}

.uvq13-prm .me .lv b {
  width: 3px;
  height: 100%;
  border-radius: 2px;
  background: #4ade80;
  transform-origin: 50% 100%;
  animation: uvq13-prm-l calc(0.5s / var(--k)) ease-in-out infinite alternate;
}

.uvq13-prm .me .lv b:nth-child(2) {
  animation-delay: -.2s;
}

.uvq13-prm .me .lv b:nth-child(3) {
  animation-delay: -.35s;
}

.uvq13-prm .tag {
  position: absolute;
  left: .5em;
  top: .45em;
  padding: .15em .5em;
  border-radius: .4em;
  font-size: .6em;
  color: #fff;
  background: rgba(0,0,0,.45);
}

.uvq13-prm .mt {
  display: grid;
  margin: 0;
  align-self: end;
}

.uvq13-prm .mt b {
  font-size: .85em;
}

.uvq13-prm .mt small {
  font-size: .68em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-prm .jn {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  justify-self: start;
  align-self: start;
  padding: .6em 1em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 700;
  color: #fff;
  background: var(--c1);
}

.uvq13-prm .po {
  position: absolute;
  left: 3.1em;
  top: 3.2em;
  z-index: 5;
  width: 13.2em;
  padding: .9em 1em 1em;
  box-sizing: border-box;
  border-radius: .8em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.6em 3.2em -1.2em rgba(0,0,0,.5);
  background: var(--bg);
  transform-origin: 1.4em 0;
  transform: translateY(-.4em) scale(.96);
  opacity: 0;
  pointer-events: none;
  transition: transform calc(0.25s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-prm.open .po {
  transform: none;
  opacity: 1;
  pointer-events: auto;
}

.uvq13-prm .po::before {
  content: "";
  position: absolute;
  left: 1.15em;
  top: -.4em;
  width: .8em;
  height: .8em;
  background: inherit;
  transform: rotate(45deg);
  box-shadow: -1px -1px 0 color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-prm .po .x {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: .45em;
  top: .45em;
  display: grid;
  place-items: center;
  width: 1.8em;
  height: 1.8em;
  border-radius: 50%;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-prm .po .x svg {
  width: .9em;
  height: .9em;
}

.uvq13-prm .ti {
  margin: 0;
  padding-right: 1.6em;
  font-size: .82em;
  font-weight: 700;
}

.uvq13-prm .dm {
  margin: .1em 0 .7em;
  font-size: .72em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-prm .rw {
  display: flex;
  align-items: center;
  gap: .6em;
  margin: 0 0 .45em;
  font-size: .8em;
}

.uvq13-prm .rw svg {
  width: 1.25em;
  height: 1.25em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-prm .ac {
  display: grid;
  gap: .35em;
  margin-top: .8em;
}

.uvq13-prm .ac button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .55em .8em;
  border-radius: 2em;
  font-size: .74em;
  font-weight: 650;
  color: var(--c1);
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
  transition: background calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-prm .ac button:hover {
  background: color-mix(in srgb,var(--c1) 9%,transparent);
}

.uvq13-prm .ac button:active {
  transform: scale(.98);
}

.uvq13-prm button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@keyframes uvq13-prm-d {
  50% {
    opacity: .35;
  }
}

@keyframes uvq13-prm-i {
  from {
    opacity: 0;
  }
}

@keyframes uvq13-prm-b {
  50% {
    transform: translateY(.12em) rotate(3deg);
  }
}

@keyframes uvq13-prm-l {
  from {
    transform: scaleY(.3);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq13-prm,.uvq13-prm *,.uvq13-prm *::before,.uvq13-prm *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

