.uvq13-cmt {
  --c1: #f59e0b;
  --c2: #0284c7;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq13-cmt {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 18em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-cmt .doc {
  position: absolute;
  left: 1em;
  top: 1em;
  bottom: 1em;
  width: 12.4em;
  padding: 1em 1.1em;
  box-sizing: border-box;
  border-radius: .6em;
  background: var(--bg);
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 .5em 1.2em -.8em rgba(0,0,0,.3);
}

.uvq13-cmt .kk {
  margin: 0;
  font-size: .58em;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-cmt .h {
  margin: .3em 0 .5em;
  font-size: .95em;
  font-weight: 800;
  line-height: 1.15;
  outline: 0;
}

.uvq13-cmt .tx {
  margin: 0 0 .6em;
  font-size: .66em;
  line-height: 1.6;
}

.uvq13-cmt .hl {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: inline;
  padding: 0 .1em;
  border-radius: .15em;
  text-align: left;
  background: color-mix(in srgb,var(--c1) 28%,transparent);
  box-shadow: inset 0 -2px 0 var(--c1);
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
  transition: background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-cmt .hl:hover,.uvq13-cmt .hl[aria-expanded="true"] {
  background: color-mix(in srgb,var(--c1) 55%,transparent);
}

.uvq13-cmt .hl:disabled {
  color: inherit;
  background: none;
  box-shadow: none;
  cursor: text;
}

.uvq13-cmt .hl:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq13-cmt .bg {
  position: absolute;
  left: 19.6em;
  display: grid;
  place-items: center;
  width: 1.7em;
  height: 1.5em;
  border-radius: .6em .6em .6em .15em;
  font-size: .72em;
  font-weight: 800;
  color: #fff;
  background: var(--c2);
  cursor: pointer;
  transition: opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq13-cmt .bg.on {
  opacity: 0;
  transform: scale(.5);
}

.uvq13-cmt .bg.done {
  display: none;
}

.uvq13-cmt .ln {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

.uvq13-cmt .ln path {
  fill: none;
  stroke: var(--c1);
  stroke-width: 1.5;
  stroke-dasharray: 3 3;
  opacity: 0;
  transition: opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-cmt.open .ln path {
  opacity: 1;
}

.uvq13-cmt .cm {
  position: absolute;
  left: 14.1em;
  top: 1em;
  z-index: 3;
  width: 7.2em;
  padding: .6em;
  box-sizing: border-box;
  border-radius: .7em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.6em 3.2em -1.2em rgba(0,0,0,.5);
  background: var(--bg);
  opacity: 0;
  transform: translateX(.8em);
  pointer-events: none;
  transition: opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.35s / var(--k)) cubic-bezier(.22,1,.36,1),top calc(0.3s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq13-cmt .cm.on {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

.uvq13-cmt ul {
  list-style: none;
  display: grid;
  gap: .55em;
  margin: 0;
  padding: 0;
}

.uvq13-cmt li {
  display: flex;
  gap: .4em;
  font-size: .6em;
}

.uvq13-cmt .av {
  display: grid;
  place-items: center;
  flex: none;
  width: 1.9em;
  height: 1.9em;
  border-radius: 50%;
  font-weight: 800;
  color: #fff;
  background: var(--c);
}

.uvq13-cmt li small {
  margin-left: .35em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-cmt li p {
  margin: .15em 0 0;
  line-height: 1.35;
}

.uvq13-cmt .rp {
  display: flex;
  gap: .3em;
  margin-top: .6em;
}

.uvq13-cmt .rp input {
  flex: 1;
  min-width: 0;
  padding: .4em .5em;
  border: 0;
  outline: 0;
