.uvq13-rsz {
  --c1: #db2777;
  --c2: #fce7f3;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq13-rsz {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 18em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-rsz .tt {
  margin: 0;
  padding: 1em 1.1em .5em;
  font-weight: 800;
}

.uvq13-rsz .gr {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: .4em;
  padding: 0 1.1em;
}

.uvq13-rsz .ph {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  aspect-ratio: 1;
  border-radius: .6em;
  background: radial-gradient(circle at 70% 30%,rgba(255,255,255,.5) 0 12%,transparent 13%),linear-gradient(160deg,var(--a),var(--b));
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.34,1.56,.64,1),box-shadow calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-rsz .ph:hover {
  transform: scale(1.03);
}

.uvq13-rsz .ph.on {
  box-shadow: 0 0 0 2px var(--bg),0 0 0 4px var(--c1);
}

.uvq13-rsz .ph:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq13-rsz .snap {
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  opacity: 0;
  transition: opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-rsz.rs .snap {
  opacity: 1;
}

.uvq13-rsz .snap i {
  position: absolute;
  top: 0;
  bottom: 0;
  right: calc(var(--d) * 1em);
  border-left: 1.5px dashed color-mix(in srgb,var(--c1) 70%,transparent);
}

.uvq13-rsz .pn {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 5;
  width: calc(var(--w,11.5) * 1em);
  box-sizing: border-box;
  container-type: inline-size;
  background: var(--bg);
  box-shadow: -1px 0 0 color-mix(in srgb,var(--fg) 9%,transparent),-1em 0 2em -1em rgba(0,0,0,.35);
  transform: translateX(105%);
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1),width calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq13-rsz.open .pn {
  transform: none;
}

.uvq13-rsz .pn.dr {
  transition: none;
}

.uvq13-rsz .hd {
  position: absolute;
  left: -.6em;
  top: 0;
  bottom: 0;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 1.2em;
  cursor: ew-resize;
  touch-action: none;
  outline: 0;
}

.uvq13-rsz .hd i {
  width: .32em;
  height: 2.6em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 22%,transparent);
  transition: background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),height calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq13-rsz .hd:hover i,.uvq13-rsz .dr .hd i,.uvq13-rsz .hd:focus-visible i {
  height: 3.8em;
  background: var(--c1);
}

.uvq13-rsz .hd:focus-visible i {
  box-shadow: 0 0 0 3px color-mix(in srgb,var(--c1) 30%,transparent);
}

.uvq13-rsz .in {
  display: flex;
  flex-direction: column;
  gap: .5em;
  height: 100%;
  padding: .8em .9em .9em 1.1em;
  box-sizing: border-box;
  overflow: hidden;
}

.uvq13-rsz header {
  display: flex;
  align-items: center;
  gap: .4em;
}

.uvq13-rsz .fn {
  flex: 1;
  min-width: 0;
  font-size: .74em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.uvq13-rsz .x {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  flex: none;
  width: 1.8em;
  height: 1.8em;
  border-radius: 50%;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq13-rsz .x svg {
  width: .9em;
  height: .9em;
}

.uvq13-rsz .pre {
  display: block;
  flex: none;
  aspect-ratio: 16/9;
  border-radius: .6em;
  background: radial-gradient(circle at 70% 30%,rgba(255,255,255,.5) 0 12%,transparent 13%),linear-gradient(160deg,var(--a,#ccc),var(--b,#999));
}

.uvq13-rsz .mt {
  display: none;
  margin: 0;
}

.uvq13-rsz .mt div {
  display: flex;
  justify-content: space-between;
  gap: .5em;
  padding: .3em 0;
  font-size: .66em;
  border-bottom: 1px solid color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-rsz dt {
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-rsz dd {
  margin: 0;
  font-weight: 650;
  text-align: right;
}

.uvq13-rsz .act {
  display: flex;
  flex-direction: column;
  gap: .35em;
  margin-top: auto;
}

.uvq13-rsz .act button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .4em;
  padding: .55em;
  border-radius: .6em;
  font-size: .72em;
  font-weight: 700;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq13-rsz .act button:first-child {
  color: var(--c1);
  background: var(--c2);
}

.uvq13-rsz .act svg {
  width: 1.2em;
  height: 1.2em;
}

.uvq13-rsz .act span {
  display: none;
}

.uvq13-rsz button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@container (min-width: 10em) {
  .uvq13-rsz .mt {
    display: block;
  }
  .uvq13-rsz .act {
    flex-direction: row;
  }
  .uvq13-rsz .act button {
    flex: 1;
  }
  .uvq13-rsz .act button:first-child span {
    display: inline;
  }
  .uvq13-rsz .fn {
    font-size: .85em;
  }
}

@container (min-width: 14em) {
  .uvq13-rsz .act span {
    display: inline;
  }
  .uvq13-rsz .in {
    display: grid;
    grid-template-columns: 1.1fr 1fr;
    grid-template-rows: auto 1fr auto;
    align-content: start;
  }
  .uvq13-rsz header {
    grid-column: 1/-1;
  }
  .uvq13-rsz .pre {
    grid-row: 2;
    aspect-ratio: auto;
    height: 100%;
  }
  .uvq13-rsz .mt {
    grid-row: 2;
  }
  .uvq13-rsz .act {
    grid-column: 1/-1;
  }
  .uvq13-rsz .fn {
    font-size: 1em;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq13-rsz,.uvq13-rsz *,.uvq13-rsz *::before,.uvq13-rsz *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

