.uvq13-ext {
  --c1: #ea580c;
  --c2: #fff7ed;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq13-ext {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 18em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-ext .ez {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  z-index: 3;
  height: .25em;
  background: linear-gradient(90deg,transparent,var(--c1) 30% 70%,transparent);
  opacity: calc(.2 + var(--near,0) * .8);
  box-shadow: 0 0 calc(var(--near,0) * 1.4em) var(--c1);
  pointer-events: none;
}

.uvq13-ext .ez span {
  position: absolute;
  left: 50%;
  top: .6em;
  padding: .25em .6em;
  border-radius: 2em;
  font-size: .6em;
  font-weight: 700;
  white-space: nowrap;
  color: var(--c1);
  background: var(--bg);
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--c1) 35%,transparent);
  transform: translate(-50%,calc((1 - var(--near,0)) * -.4em));
  opacity: calc(.55 + var(--near,0) * .45);
}

.uvq13-ext .nv {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 2em 1.2em .8em;
}

.uvq13-ext .nv b {
  font-size: 1.05em;
  font-weight: 900;
  letter-spacing: -.04em;
}

.uvq13-ext .ct {
  position: relative;
  display: grid;
  place-items: center;
  width: 2em;
  height: 2em;
}

.uvq13-ext .ct svg {
  width: 1.3em;
  height: 1.3em;
}

.uvq13-ext .ct i {
  position: absolute;
  right: -.1em;
  top: -.1em;
  display: grid;
  place-items: center;
  min-width: 1.2em;
  height: 1.2em;
  border-radius: 1em;
  font-size: .62em;
  font-style: normal;
  font-weight: 800;
  color: #fff;
  background: var(--c1);
}

.uvq13-ext .gr {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: .6em;
  padding: 0 1.2em;
}

.uvq13-ext .gr span {
  display: grid;
  gap: .4em;
}

.uvq13-ext .gr i {
  height: .5em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq13-ext .gr .p {
  height: 4.2em;
  border-radius: .7em;
  background: color-mix(in srgb,var(--fg) 7%,transparent);
}

.uvq13-ext .gr .s {
  width: 60%;
}

.uvq13-ext .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  left: 50%;
  bottom: 1em;
  padding: .55em 1em;
  border-radius: 2em;
  font-size: .76em;
  font-weight: 700;
  color: var(--bg);
  background: var(--fg);
  transform: translateX(-50%);
}

.uvq13-ext .scr {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: rgba(20,10,4,.45);
  opacity: 0;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-ext.open .scr {
  opacity: 1;
  pointer-events: auto;
}

.uvq13-ext .dl {
  position: absolute;
  left: 50%;
  top: 1em;
  z-index: 5;
  width: 14.6em;
  padding: 1.1em 1.2em 1em;
  box-sizing: border-box;
  border-radius: 1.2em;
  text-align: center;
  color: #2b1607;
  background: var(--c2);
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--c1) 25%,transparent),0 1.6em 3em -1em rgba(0,0,0,.55);
  transform: translate(-50%,-120%);
  transition: transform calc(0.55s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq13-ext.open .dl {
  transform: translate(-50%,0);
}

.uvq13-ext .x {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: .6em;
  top: .6em;
  display: grid;
  place-items: center;
  width: 1.8em;
  height: 1.8em;
  border-radius: 50%;
  color: #2b1607;
  background: rgba(0,0,0,.06);
}

.uvq13-ext .x svg {
  width: .9em;
  height: .9em;
}

.uvq13-ext .ti {
  margin: 0;
  font-size: 1.2em;
  font-weight: 850;
  letter-spacing: -.02em;
}

.uvq13-ext .ds {
  margin: .3em 0 .7em;
  font-size: .74em;
  opacity: .75;
}

.uvq13-ext .its {
  display: flex;
  justify-content: center;
  gap: .4em;
  margin-bottom: .8em;
}

.uvq13-ext .its i {
  width: 2.6em;
  height: 2.6em;
  border-radius: .6em;
  background: linear-gradient(160deg,color-mix(in srgb,var(--c) 45%,#fff),var(--c));
  box-shadow: 0 .3em .6em -.3em rgba(0,0,0,.4);
  transform: rotate(-4deg);
}

.uvq13-ext .its i+i {
  transform: rotate(5deg);
}

.uvq13-ext .fm {
  display: flex;
  gap: .3em;
  padding: .25em;
  border-radius: .8em;
  background: #fff;
  box-shadow: 0 0 0 1px rgba(0,0,0,.08);
}

.uvq13-ext .fm.bad {
  animation: uvq13-ext-s calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
  box-shadow: 0 0 0 2px #dc2626;
}

.uvq13-ext .fm input {
  flex: 1;
  min-width: 0;
  padding: 0 .5em;
  border: 0;
  outline: 0;
  background: none;
  font: inherit;
  font-size: .78em;
  color: #2b1607;
}

.uvq13-ext .fm button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .55em .8em;
  border-radius: .6em;
  font-size: .74em;
  font-weight: 700;
  color: #fff;
  background: var(--c1);
}

.uvq13-ext .no {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  margin-top: .6em;
  font-size: .7em;
  font-weight: 650;
  opacity: .65;
  text-decoration: underline;
  text-underline-offset: .2em;
}

.uvq13-ext .v2 {
  display: none;
}

.uvq13-ext .sent .v1 {
  display: none;
}

.uvq13-ext .sent .v2 {
  display: block;
  animation: uvq13-ext-i calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq13-ext .ok {
  display: grid;
  place-items: center;
  width: 2.8em;
  height: 2.8em;
  margin: 0 auto .5em;
  border-radius: 50%;
  color: #fff;
  background: var(--c1);
}

.uvq13-ext .ok svg {
  width: 1.4em;
  height: 1.4em;
}

.uvq13-ext button:focus-visible,.uvq13-ext .fm:focus-within {
  outline: 2px solid var(--c1);
  outline-offset: 2px;
}

@keyframes uvq13-ext-s {
  20%,60% {
    transform: translateX(-.3em);
  }
  40%,80% {
    transform: translateX(.3em);
  }
}

@keyframes uvq13-ext-i {
  from {
    opacity: 0;
    transform: scale(.92);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq13-ext,.uvq13-ext *,.uvq13-ext *::before,.uvq13-ext *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

