.uvq13-snz {
  --c1: #0891b2;
  --c2: #fde68a;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq13-snz {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 20em;
  border-radius: 1.2em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent);
}

.uvq13-snz .hh {
  margin: 0;
  padding: 1em 1.1em .4em;
  font-weight: 800;
}

.uvq13-snz .ib {
  list-style: none;
  margin: 0;
  padding: 0 .6em;
}

.uvq13-snz .r {
  display: flex;
  align-items: center;
  gap: .6em;
  height: 3em;
  padding: 0 .6em;
  border-radius: .7em;
  overflow: hidden;
  transition: height calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-snz .r.on {
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq13-snz .r.gone {
  height: 0;
  opacity: 0;
}

.uvq13-snz .av {
  display: grid;
  place-items: center;
  flex: none;
  width: 2em;
  height: 2em;
  border-radius: 50%;
  font-size: .85em;
  font-weight: 800;
  color: #fff;
  background: var(--c);
}

.uvq13-snz .tx {
  flex: 1;
  min-width: 0;
  display: grid;
  font-size: .78em;
}

.uvq13-snz .tx span {
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.uvq13-snz .r small {
  font-size: .66em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-snz .ha {
  display: flex;
  gap: .2em;
}

.uvq13-snz .ha button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 2em;
  height: 2em;
  border-radius: 50%;
  transition: background calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-snz .ha button:hover,.uvq13-snz.open .fire {
  color: var(--c1);
  background: color-mix(in srgb,var(--c1) 14%,transparent);
}

.uvq13-snz .ha svg {
  width: 1.15em;
  height: 1.15em;
}

.uvq13-snz .po {
  position: absolute;
  right: 1.1em;
  top: 5.5em;
  z-index: 5;
  width: 15.6em;
  padding: .45em;
  box-sizing: border-box;
  border-radius: .9em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.6em 3.2em -1.2em rgba(0,0,0,.5);
  background: var(--bg);
  transform-origin: 90% 0;
  transform: scale(.92) translateY(-.4em);
  opacity: 0;
  pointer-events: none;
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-snz.open .po {
  transform: none;
  opacity: 1;
  pointer-events: auto;
}

.uvq13-snz .pt {
  margin: .2em .5em .3em;
  font-size: .62em;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq13-snz .op {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: flex;
  align-items: center;
  gap: .6em;
  box-sizing: border-box;
  width: 100%;
  padding: .34em .5em;
  border-radius: .6em;
  font-size: .76em;
  text-align: left;
  transition: background calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq13-snz .op:hover,.uvq13-snz .op:focus-visible {
  outline: 0;
  background: color-mix(in srgb,var(--c1) 12%,transparent);
}

.uvq13-snz .op span {
  flex: 1;
  white-space: nowrap;
}

.uvq13-snz .op small {
  white-space: nowrap;
  font-size: .9em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  font-variant-numeric: tabular-nums;
}

.uvq13-snz .sk {
  position: relative;
  flex: none;
  width: 1.8em;
  height: 1.8em;
  border-radius: .5em;
  overflow: hidden;
}

.uvq13-snz .sk::before {
  content: "";
  position: absolute;
  left: var(--sx,50%);
  top: var(--sy,50%);
  width: .6em;
  height: .6em;
  margin: -.3em;
  border-radius: 50%;
  background: #fff7d6;
  box-shadow: 0 0 .4em #fde68a;
  transition: transform calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq13-snz .sk::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 28%;
  background: rgba(0,0,0,.25);
}

.uvq13-snz .ev {
  --sx: 72%;
  --sy: 62%;
  background: linear-gradient(180deg,#7c3aed,#f97316);
}

.uvq13-snz .tm {
  --sx: 28%;
  --sy: 64%;
  background: linear-gradient(180deg,#93c5fd,#fbcfe8);
}

.uvq13-snz .we {
  --sx: 50%;
  --sy: 30%;
  background: linear-gradient(180deg,#38bdf8,#bae6fd);
}

.uvq13-snz .nw {
  --sx: 30%;
  --sy: 44%;
  background: linear-gradient(180deg,#1e3a8a,var(--c1));
}

.uvq13-snz .pk {
  background: color-mix(in srgb,var(--c2) 70%,var(--bg));
}

.uvq13-snz .pk::before {
  left: 50%;
  top: 50%;
  width: .95em;
  height: .85em;
  margin: -.42em -.47em;
  border-radius: .15em;
  background: linear-gradient(var(--c1) 0 .25em,#fff 0);
  box-shadow: none;
}

.uvq13-snz .pk::after {
  display: none;
}

.uvq13-snz .op:hover .sk:not(.pk)::before,.uvq13-snz .op:focus-visible .sk:not(.pk)::before {
  transform: translateY(-.3em);
}

.uvq13-snz .cu {
  display: none;
  padding: .4em .5em .5em;
}

.uvq13-snz .po.pick .cu {
  display: block;
  animation: uvq13-snz-i calc(0.3s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq13-snz .dy {
  display: grid;
  grid-template-columns: repeat(7,1fr);
  gap: .2em;
  margin-bottom: .4em;
}

.uvq13-snz .dy button,.uvq13-snz .hs button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .3em 0;
  border-radius: .4em;
  font-size: .6em;
  line-height: 1.2;
  text-align: center;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq13-snz .dy b {
  display: block;
  font-size: 1.25em;
}

.uvq13-snz .hs {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: .25em;
  margin-bottom: .45em;
}

.uvq13-snz .hs button {
  font-size: .66em;
  padding: .4em 0;
}

.uvq13-snz [aria-pressed="true"] {
  color: #fff;
  background: var(--c1);
}

.uvq13-snz .sv {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  width: 100%;
  padding: .5em;
  border-radius: .5em;
  font-size: .72em;
  font-weight: 700;
  color: #fff;
  background: var(--c1);
}

.uvq13-snz button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq13-snz .op:focus-visible {
  box-shadow: inset 0 0 0 2px var(--c1);
}

.uvq13-snz .tst {
  position: absolute;
  left: 1em;
  right: 1em;
  bottom: 1em;
  z-index: 6;
  display: flex;
  align-items: center;
  gap: .6em;
  margin: 0;
  padding: .55em .6em .55em .9em;
  border-radius: .8em;
  font-size: .74em;
  color: var(--bg);
  background: var(--fg);
  opacity: 0;
  transform: translateY(.6em);
  pointer-events: none;
  transition: opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq13-snz .tst.on {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

.uvq13-snz .tst .m {
  flex: 1;
}

.uvq13-snz .un {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .35em .6em;
  border-radius: .5em;
  font-weight: 800;
  color: var(--c2);
}

@keyframes uvq13-snz-i {
  from {
    opacity: 0;
    transform: translateY(-.3em);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq13-snz,.uvq13-snz *,.uvq13-snz *::before,.uvq13-snz *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

