const L=document.documentElement.lang||undefined,wd=d=>new Intl.DateTimeFormat(L,{weekday:"short"}).format(d),hm=(h,m)=>{const d=new Date();d.setHours(h,m||0,0,0);return new Intl.DateTimeFormat(L,{hour:"numeric",minute:"2-digit"}).format(d)};
