const press=(g,b)=>[...(g.children||g)].forEach(x=>x.setAttribute("aria-pressed",String(x===b)));
hs.forEach(b=>b.addEventListener("click",()=>press(hs,b)));
const done=txt=>{close();row.classList.add("gone");foc(".un",60);tst.querySelector(".m").textContent=txt;tst.classList.add("on");clearTimeout(tt);tt=setTimeout(()=>tst.classList.remove("on"),4500)};
ops.forEach((o,i)=>{o.addEventListener("click",()=>{if(o.dataset.k==="pk"){po.classList.add("pick");later(()=>dy.firstChild&&dy.firstChild.focus({preventScroll:true}),60);return}done(o.querySelector("span").textContent+" · "+o.querySelector("small").textContent)});o.addEventListener("keydown",e=>{const m={ArrowDown:1,ArrowUp:-1}[e.key];if(m){e.preventDefault();ops[(i+m+ops.length)%ops.length].focus()}})});
el.querySelector(".sv").addEventListener("click",()=>{const d=dy.querySelector("[aria-pressed='true']"),h=hs.find(x=>x.getAttribute("aria-pressed")==="true");done((d?d.textContent.replace(/(\D+)(\d+)/,"$1 $2"):"")+" · "+h.textContent)});
el.querySelector(".un").addEventListener("click",()=>{row.classList.remove("gone");tst.classList.remove("on");fire.focus({preventScroll:true})});
el.addEventListener("pointerdown",e=>{if(isOpen()&&!e.target.closest(".po,.fire"))close()});
return()=>{tms.forEach(clearTimeout);clearTimeout(tt)}
});

